contract SelfCustodyVaultV2(
    pubkey hotKey,
    pubkey coldKey,
    pubkey[] whitelistedDestinations,
    int whitelistCount,
    int initUnvaultDelayDaa,
    int initPhase
) {
    int constant PHASE_LOCKED = 0;
    int constant PHASE_UNVAULTING = 1;

    int phase = initPhase;
    int unvaultDelayDaa = initUnvaultDelayDaa;
    int activeWhitelistCount = whitelistCount;

    function requireValidPolicy() {
        require(activeWhitelistCount >= 0);
        require(activeWhitelistCount <= whitelistedDestinations.length);
        require(unvaultDelayDaa > 0);
    }

    function requireDestination(int outputIndex, int destinationIndex) {
        if (activeWhitelistCount > 0) {
            require(destinationIndex >= 0);
            require(destinationIndex < activeWhitelistCount);
            require(tx.outputs[outputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(whitelistedDestinations[destinationIndex])));
        }
    }

    function validateVaultOutput(int outputIndex, int nextPhase) {
        validateOutputState(outputIndex, {
            phase: nextPhase,
            unvaultDelayDaa: unvaultDelayDaa,
            activeWhitelistCount: activeWhitelistCount
        });
    }

    entrypoint function topUp() {
        requireValidPolicy();
        require(phase == PHASE_LOCKED);
        require(this.activeInputIndex == 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == 0);
        require(tx.outputs[0].value > tx.inputs[this.activeInputIndex].value);
        validateVaultOutput(0, PHASE_LOCKED);
    }

    entrypoint function unvault(sig hotSig) {
        require(checkSig(hotSig, hotKey));
        requireValidPolicy();
        require(phase == PHASE_LOCKED);
        require(this.activeInputIndex == 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == 0);
        require(tx.outputs[0].value == tx.inputs[this.activeInputIndex].value);
        validateVaultOutput(0, PHASE_UNVAULTING);
    }

    entrypoint function emergencySweep(sig coldSig, int destinationIndex) {
        require(checkSig(coldSig, coldKey));
        requireValidPolicy();
        require(this.activeInputIndex == 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 0);
        require(tx.outputs[0].value == tx.inputs[this.activeInputIndex].value);
        requireDestination(0, destinationIndex);
    }

    entrypoint function finalizeAll(sig hotSig, int destinationIndex) {
        require(checkSig(hotSig, hotKey));
        requireValidPolicy();
        require(phase == PHASE_UNVAULTING);
        require(this.age >= unvaultDelayDaa);
        require(this.activeInputIndex == 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 0);
        require(tx.outputs[0].value == tx.inputs[this.activeInputIndex].value);
        requireDestination(0, destinationIndex);
    }

    entrypoint function finalizePartial(sig hotSig, int destinationIndex, int withdrawalAmount) {
        require(checkSig(hotSig, hotKey));
        requireValidPolicy();
        require(phase == PHASE_UNVAULTING);
        require(this.age >= unvaultDelayDaa);
        require(this.activeInputIndex == 0);
        require(withdrawalAmount > 0);
        require(withdrawalAmount < tx.inputs[this.activeInputIndex].value);
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == 1);
        require(tx.outputs[0].value == withdrawalAmount);
        require(tx.outputs[1].value == tx.inputs[this.activeInputIndex].value - withdrawalAmount);
        requireDestination(0, destinationIndex);
        validateVaultOutput(1, PHASE_LOCKED);
    }
}
